  pros = ARRAY['מקורות מצוטטים תמיד', 'מידע בזמן אמת', 'מצב Pro עם מודלים מתקדמים', 'גרסה חינמית שימושית מאוד'],
  cons = ARRAY['פחות יצירתי מ-ChatGPT לכתיבה', 'הרמה החינמית עם מגבלות חיפוש Pro', 'עלול לערבב מקורות באיכות משתנה']
WHERE slug = 'perplexity' AND lang = 'he';

UPDATE tools SET
