  pros = ARRAY['משולב נטיבית ב-Microsoft 365', 'הקשר מלא של מסמכים ואימיילים', 'סיכום פגישות ב-Teams', 'יצירת מצגות ב-PowerPoint'],
  cons = ARRAY['דורש רישיון Microsoft 365 Copilot ב-$30/משתמש/חודש', 'איכות משתנה לפי אפליקציה', 'פחות חזק מחוץ למערכת האקולוגית של Microsoft']
WHERE slug = 'microsoft-copilot' AND lang = 'he';

UPDATE tools SET
