  pros = ARRAY['חינמי לחלוטין', 'משולב ב-WhatsApp ו-Instagram', 'זמין למיליארדי משתמשים', 'יצירת תמונות כלולה'],
  cons = ARRAY['פחות חזק מ-ChatGPT או Claude למשימות מורכבות', 'חששות פרטיות עם Meta', 'התאמה אישית מוגבלת']
WHERE slug = 'meta-ai' AND lang = 'he';
